/**
 * The federated genealogy (Phase 6 slice 6i; recipe-core 1090, 1091; L-41, PR-57, IN-29; D-P6i-0-7, D-P6i-0-9).
 *
 * Asking: for a TRANSFER node the database reached, the server asks the installation at the other end of the transfer.
 * The request is built by this database (recipe.issue_federated_request: nonce, issued-at, query) and sealed with this
 * installation's key; the answer is kept only if this database verifies the other installation's seal and that it
 * answers exactly what was asked (recipe.record_federated_excerpt). A site that does not answer (or refuses, or answers
 * wrongly) is logged with an alarm (recipe.record_federation_failure); the last excerpt received is shown with its own,
 * older as-of point and the part is not ANSWERED, so the result says it is incomplete (never silently partial).
 *
 * Answering: the endpoint hands the sealed request to recipe.answer_federated_genealogy, which checks the seal, the
 * destination, the time and the nonce, and that the transfer was exchanged with the caller; the server seals the
 * excerpt the database built.
 */
import type pg from 'pg';
import type { FederatedPartStatus, FederatedPartView, FederatedTraceView, GenealogyDirection, GenealogyEdgeView, GenealogyNodeKind, GenealogyNodeView } from '@ebmr/api-contract';
import type { AppContext } from '../../platform/context.ts';
import { trace } from '../genealogy/reads.ts';
import { loadInstallationKey, type InstallationKey } from './keys.ts';

type Db = Pick<pg.PoolClient, 'query'>;

const keys = new WeakMap<AppContext, InstallationKey | null>();

/** This server's installation key (EBMR_INSTALLATION_KEY_FILE), read once per server; null when none is configured. */
export function installationKey(app: AppContext): InstallationKey | null {
  if (!keys.has(app)) keys.set(app, loadInstallationKey(app.config.installationKeyFile));
  return keys.get(app) ?? null;
}

interface ExcerptRow {
  nodeKind: GenealogyNodeKind;
  nodeId: string;
  parentKind: GenealogyNodeKind | null;
  parentId: string | null;
  edgeKind: GenealogyEdgeView['edgeKind'];
  depth: number;
}
interface ExcerptNode {
  kind: GenealogyNodeKind;
  id: string;
  label: string;
  code: string | null;
  name: string | null;
  sub_kind: string | null;
  state: string | null;
}
export interface Excerpt {
  asOfUs: string;
  rows: ExcerptRow[];
  nodes: ExcerptNode[];
}

export interface PeerAnswer {
  status: FederatedPartStatus;
  detail: string | null;
  /** The excerpt shown: the answer (ANSWERED) or the last one received before (its own as-of), or none. */
  excerpt: Excerpt | null;
  excerptId: string | null;
  excerptAsOfUs: string | null;
}

const excerptOf = (payload: string): Excerpt => {
  const p = JSON.parse(payload) as { asOfUs: string; rows: ExcerptRow[]; nodes: ExcerptNode[] };
  return { asOfUs: p.asOfUs, rows: p.rows, nodes: p.nodes };
};

/** The last excerpt this site received for (peer, transfer, direction), whatever its as-of. */
async function lastExcerpt(db: Db, peer: string, transferId: string, direction: GenealogyDirection): Promise<{ id: string; payload: string } | null> {
  const { rows } = await db.query<{ id: string | null; payload: string | null }>(
    'select (e).id::text as id, (e).payload as payload from (select recipe.last_federated_excerpt($1, $2, $3) as e) x', [peer, transferId, direction]);
  return rows[0]?.id && rows[0].payload ? { id: rows[0].id, payload: rows[0].payload } : null;
}

const reasonOf = (text: string): string => {
  try {
    const j = JSON.parse(text) as { why?: unknown; whatHappened?: unknown; code?: unknown };
    return [j.code, j.why ?? j.whatHappened].filter((x) => typeof x === 'string').join(' ') || text.slice(0, 500);
  } catch {
    return text.slice(0, 500);
  }
};

/**
 * Asks `peer` for its genealogy from `transferId` in `direction` as of `asOfUs`, inside the asking person's command
 * (`db` is its client). Never throws for the other site's failure: it is the part's status, logged with an alarm.
 */
export async function askPeer(app: AppContext, db: Db, peer: string, transferId: string, direction: GenealogyDirection, asOfUs: string): Promise<PeerAnswer> {
  let issued: { nonce: string; request: string; baseUrl: string };
  // The caller's command (the person's, GENEALOGY.FEDERATE; recipe-core 1093): a refused issue rolls back to here only.
  await db.query('savepoint federation_issue');
  try {
    issued = (await db.query<{ r: { nonce: string; request: string; baseUrl: string } }>(
      "select recipe.issue_federated_request($1, $2, $3, timestamptz 'epoch' + ($4::bigint * interval '1 microsecond')) as r", [peer, transferId, direction, asOfUs])).rows[0]!.r;
    await db.query('release savepoint federation_issue');
  } catch (error) {
    await db.query('rollback to savepoint federation_issue');
    const last = await lastExcerpt(db, peer, transferId, direction);
    return { status: 'NOT_REGISTERED', detail: error instanceof Error ? error.message : String(error), excerpt: last ? excerptOf(last.payload) : null, excerptId: last?.id ?? null, excerptAsOfUs: last ? excerptOf(last.payload).asOfUs : null };
  }
  const fail = async (status: 'UNREACHABLE' | 'REFUSED' | 'WRONG_ANSWER', detail: string, record = true): Promise<PeerAnswer> => {
    if (record) await db.query('select recipe.record_federation_failure($1, $2, $3)', [issued.nonce, status, detail]);
    const last = await lastExcerpt(db, peer, transferId, direction);
    return { status, detail, excerpt: last ? excerptOf(last.payload) : null, excerptId: last?.id ?? null, excerptAsOfUs: last ? excerptOf(last.payload).asOfUs : null };
  };
  const key = installationKey(app);
  if (!key) return fail('REFUSED', 'EBMR-FED-020 this server holds no installation key, so it cannot seal a request (EBMR_INSTALLATION_KEY_FILE)');
  if (app.config.env === 'production' && !issued.baseUrl.startsWith('https://')) {
    return fail('REFUSED', `EBMR-FED-021 ${peer} is registered with an http address; production calls other installations over https only (DI-13)`);
  }
  let res: Response;
  try {
    res = await fetch(`${issued.baseUrl.replace(/\/+$/, '')}/api/federation/genealogy`, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ request: issued.request, seal: key.seal('federation-request', issued.request) }),
      signal: AbortSignal.timeout(app.config.federationTimeoutS * 1000),
    });
  } catch (error) {
    return fail('UNREACHABLE', `${peer} did not answer within ${app.config.federationTimeoutS} seconds (${error instanceof Error ? (error.cause instanceof Error ? error.cause.message : error.message) : String(error)})`);
  }
  const text = await res.text().catch(() => '');
  if (res.status !== 200) return fail('REFUSED', `${peer} refused the request (HTTP ${res.status}): ${reasonOf(text)}`);
  let body: { payload?: unknown; seal?: unknown };
  try {
    body = JSON.parse(text) as { payload?: unknown; seal?: unknown };
  } catch {
    body = {};
  }
  if (typeof body.payload !== 'string' || typeof body.seal !== 'string') return fail('WRONG_ANSWER', `${peer} answered something that is not a sealed excerpt`);
  const rec = (await db.query<{ r: { ok: boolean; excerptId?: string; reason?: string } }>('select recipe.record_federated_excerpt($1, $2, $3) as r', [issued.nonce, body.payload, body.seal])).rows[0]!.r;
  if (!rec.ok || !rec.excerptId) return fail('WRONG_ANSWER', rec.reason ?? 'the answer was not kept', false);
  const excerpt = excerptOf(body.payload);
  return { status: 'ANSWERED', detail: null, excerpt, excerptId: rec.excerptId, excerptAsOfUs: excerpt.asOfUs };
}

/** The installation at the other end of a TRANSFER node as this site sees it. */
export const otherEnd = (n: Pick<GenealogyNodeView, 'subKind' | 'code' | 'name'>): string => (n.subKind === 'OUTBOUND' ? n.name : n.code) ?? '';

const nodeView = (n: ExcerptNode): GenealogyNodeView => ({ kind: n.kind, id: n.id, label: n.label, code: n.code, name: n.name, subKind: n.sub_kind, state: n.state });
const edgeView = (r: ExcerptRow): GenealogyEdgeView => ({
  node: { kind: r.nodeKind, id: r.nodeId },
  parent: r.parentKind && r.parentId ? { kind: r.parentKind, id: r.parentId } : null,
  edgeKind: r.edgeKind,
  depth: r.depth,
});

/** The local trace and, for every transfer it reaches, the other site's part (contract genealogy.federatedTrace). */
export async function federatedTrace(app: AppContext, db: Db, kind: GenealogyNodeKind, id: string, direction: GenealogyDirection, asked: string | undefined): Promise<FederatedTraceView> {
  const local = await trace(app, db, kind, id, direction, asked);
  const transfers = local.nodes.filter((n) => n.kind === 'TRANSFER');
  const remote: FederatedPartView[] = [];
  const beyond = new Map<string, { transferId: string; packageNo: string; peer: string }>();
  for (const t of transfers) {
    const peer = otherEnd(t);
    const a = await askPeer(app, db, peer, t.id, direction, local.asOf.us);
    const nodes = (a.excerpt?.nodes ?? []).map(nodeView);
    for (const n of nodes) {
      // Any further transfer in another site's part (to a third site, or back to this one) is beyond one hop: the result
      // says so and is incomplete (review 6i-R1; D-P6i-0-7).
      if (n.kind !== 'TRANSFER' || n.id === t.id || transfers.some((x) => x.id === n.id)) continue;
      beyond.set(n.id, { transferId: n.id, packageNo: n.label, peer: otherEnd(n) });
    }
    remote.push({
      transferId: t.id,
      packageNo: t.label,
      peer,
      status: a.status,
      askedAsOf: local.asOf,
      excerptAsOf: a.excerptAsOfUs ? app.formatInstant(a.excerptAsOfUs) : null,
      detail: a.detail,
      nodes,
      edges: (a.excerpt?.rows ?? []).map(edgeView),
    });
  }
  return {
    local,
    remote,
    complete: remote.every((p) => p.status === 'ANSWERED') && beyond.size === 0,
    beyondOneHop: [...beyond.values()],
  };
}

/**
 * Feature `transfers` (Phase 6 slice 6i, GMP): lot-transfer packages between site installations and the site-to-site
 * genealogy endpoint (contract ns/transfers.ts; kernel 1220, site services 0980, 0981, recipe-core 1090; outline L-41;
 * DI-31, DI-39, PR-57). Every rule is the database's: the package content is built by site.prepare_transfer_package and
 * the seal verified by site.seal_transfer_package, the receipt checked by site.import_transfer_package (a refusal is an
 * answer with its alarm, never a silent drop), the acceptance is the signable action TRANSFER_RECEIPT_DECIDE and a peer's
 * trust PEER_INSTALLATION_APPROVE. The server's one part is the installation key (keys.ts): it seals what the database
 * built and nothing else (D-P6i-0-8).
 */
import { readFileSync } from 'node:fs';
import { routes } from '@ebmr/api-contract';
import { identity as kernelIdentity } from '@ebmr/kernel';
import type { FastifyInstance } from 'fastify';
import type { AppContext } from '../../platform/context.ts';
import { withActorCommand, withIdempotentActorCommand } from '../../platform/db/commands.ts';
import { bindRoutes } from '../../platform/http/bind.ts';
import { refusal } from '../../platform/http/refusal.ts';
import type { SignableActionRegistry } from '../../platform/ports.ts';
import { compact } from '../common/people.ts';
import { openAdapterActor, type AdapterCredentials } from '../integrations/adapters/framework.ts';
import { installationKey } from './federation.ts';
import { TRANSFERS_GUIDANCE } from './guidance.ts';
import { alarms, identity, packageFile, peers, receipt, receipts, packages } from './reads.ts';
import { peerApproveHandler, receiptDecideHandler } from './signables.ts';

export const guidance = TRANSFERS_GUIDANCE;

/** Site-to-site requests per client address (review 6i-R3). */
export const FEDERATION_RATE = { max: 30, timeWindow: '1 minute' } as const;

export function registerSignableActions(registry: SignableActionRegistry, app: AppContext): void {
  if (app.installation !== 'GMP') return;
  registry.register(receiptDecideHandler(app));
  registry.register(peerApproveHandler(app));
}

const noKey = () =>
  refusal(503, {
    code: 'EBMR-FED-020',
    kind: 'NOT_ENABLED',
    whatHappened: 'This server holds no installation key, so it seals nothing.',
    why: 'EBMR_INSTALLATION_KEY_FILE is not configured, or names another installation or key than the database holds.',
    whatYouCanDo: ['Configure the installation key of this installation (DEMO-ONLY file; a KMS or HSM in production).'],
    whoCanHelp: ['The system administrator'],
    controls: ['DI-31'],
  });

/** The service-keys file's terminal of the federation endpoint's INTEGRATION identity (role FEDERATION_INTERFACE). */
export const FEDERATION_TERMINAL = 'SRV-FEDERATION-01';

/** The federation identity's credentials from EBMR_SERVICE_KEYS_FILE (DEMO-ONLY file); null when none is configured. */
export function federationCredentials(file: string | null): AdapterCredentials | null {
  if (!file) return null;
  const parsed = JSON.parse(readFileSync(file, 'utf8')) as { services?: { terminal: string; loginName: string; serviceKey: string; fingerprint?: string | null; terminalKey?: { fingerprint?: string } | null }[] };
  const e = (parsed.services ?? []).find((x) => x.terminal === FEDERATION_TERMINAL);
  const fingerprint = e?.terminalKey?.fingerprint ?? e?.fingerprint ?? null;
  return e && fingerprint ? { loginName: e.loginName, serviceKey: e.serviceKey, fingerprint } : null;
}

const noIdentity = () =>
  refusal(503, {
    code: 'EBMR-FED-022',
    kind: 'NOT_ENABLED',
    whatHappened: 'This server has no federation identity, so it answers no other installation.',
    why: `EBMR_SERVICE_KEYS_FILE names no ${FEDERATION_TERMINAL} service (an INTEGRATION account in role FEDERATION_INTERFACE).`,
    whatYouCanDo: ['Configure the federation endpoint\'s service identity.'],
    whoCanHelp: ['The system administrator'],
    controls: ['DI-14', 'DI-31'],
  });

export function plugin(scope: FastifyInstance, app: AppContext): Promise<void> {
  const pool = app.pools.app;
  /** The key, only when it is this installation's current one. */
  const currentKey = async () => {
    const key = installationKey(app);
    const me = await identity(pool, key);
    if (!key || !me?.serverHoldsKey) throw noKey();
    return key;
  };
  bindRoutes(scope, app, routes.transfers, {
    peers: async ({ requireSession }) => {
      requireSession();
      return { installation: await identity(pool, installationKey(app)), peers: await peers(app, pool) };
    },
    proposePeer: async ({ body, actor, idempotencyKey, requestHash }) => {
      const { result: id } = await withIdempotentActorCommand(pool, actor(), idempotencyKey ?? '', requestHash, async (c) =>
        (await c.query<{ id: string }>('select platform.propose_peer_installation($1::jsonb)::text as id', [JSON.stringify(body)])).rows[0]!.id);
      return (await peers(app, pool, id))[0]!;
    },
    packages: async ({ requireSession }) => {
      requireSession();
      return { packages: await packages(app, pool) };
    },
    prepare: async ({ body, actor, idempotencyKey, requestHash }) => {
      const key = await currentKey();
      const spec = compact({ destination: body.destination, quantity: body.quantity, markets: body.markets, holdUntil: body.holdUntil });
      const { result: id } = await withIdempotentActorCommand(pool, actor(), idempotencyKey ?? '', requestHash, async (c) => {
        const p = (await c.query<{ r: { packageId: string; payload: string } }>('select site.prepare_transfer_package($1, $2::jsonb) as r', [body.lotId, JSON.stringify(spec)])).rows[0]!.r;
        await c.query('select site.seal_transfer_package($1, $2)', [p.packageId, key.seal('transfer-package', p.payload)]);
        return p.packageId;
      });
      return packageFile(pool, id);
    },
    packageFile: async ({ params, requireSession }) => {
      requireSession();
      return packageFile(pool, params.packageId);
    },
    receipts: async ({ requireSession }) => {
      requireSession();
      return { receipts: await receipts(app, pool) };
    },
    receipt: async ({ params, requireSession }) => {
      requireSession();
      return receipt(app, pool, params.receiptId);
    },
    import: async ({ body, actor, idempotencyKey, requestHash }) => {
      const { result } = await withIdempotentActorCommand(pool, actor(), idempotencyKey ?? '', requestHash, async (c) =>
        (await c.query<{ r: { outcome: 'RECEIVED' | 'REFUSED'; receiptId?: string; kind?: string; reason?: string; alarmId?: string } }>(
          'select site.import_transfer_package($1, $2) as r', [body.payload, body.seal])).rows[0]!.r);
      if (result.outcome === 'RECEIVED') return { outcome: 'RECEIVED' as const, receipt: await receipt(app, pool, result.receiptId!) };
      return { outcome: 'REFUSED' as const, kind: result.kind as 'TAMPERED', reason: result.reason!, alarmId: result.alarmId! };
    },
    alarms: async ({ requireSession }) => {
      requireSession();
      return { alarms: await alarms(app, pool) };
    },
    acknowledgeAlarm: async ({ params, body, actor, idempotencyKey, requestHash }) => {
      await withIdempotentActorCommand(pool, actor(), idempotencyKey ?? '', requestHash, async (c) => {
        await c.query('select platform.acknowledge_installation_alarm($1, $2)', [params.alarmId, body.note]);
        return params.alarmId;
      });
      return (await alarms(app, pool, params.alarmId))[0]!;
    },
  });
  bindRoutes(scope, app, routes.federation, {
    // Site to site: no session; the request's seal under a trusted peer's key is the authentication (the database checks it).
    genealogy: async ({ body }) => {
      const key = await currentKey();
      // The answer runs as the endpoint's INTEGRATION identity (FEDERATION.ANSWER; it never signs, DI-14); the database
      // checks the request's seal, destination, time window and nonce (recipe-core 1093, kernel 1220).
      const creds = federationCredentials(app.config.serviceKeysFile);
      if (!creds) throw noIdentity();
      const fed = await openAdapterActor(app, creds, 'FEDERATION_INTERFACE');
      let r: { ok: boolean; payload?: string; reason?: string };
      try {
        r = await withActorCommand(pool, { ...fed, correlationId: crypto.randomUUID() }, async (c) =>
          (await c.query<{ r: { ok: boolean; payload?: string; reason?: string } }>('select recipe.answer_federated_genealogy($1, $2) as r', [body.request, body.seal])).rows[0]!.r);
      } finally {
        await kernelIdentity.endSession(app.pools.app, fed.sessionId);
      }
      if (!r.ok || !r.payload) {
        const code = r.reason?.match(/EBMR-[A-Z]+-\d{3}/)?.[0] ?? 'EBMR-FED-002';
        throw refusal(403, { code, kind: 'NOT_ALLOWED', whatHappened: 'The genealogy request was refused.', why: r.reason ?? 'refused', whatYouCanDo: ['Check the request and the installation keys.'], controls: ['DI-31'] });
      }
      return { payload: r.payload, seal: key.seal('federation-answer', r.payload) };
    },
    // Review 6i-R3: the route needs no session and every request costs a seal verification in the database, so it is
    // counted per client address (a refused request still leaves its alarm).
  }, { rateLimits: { genealogy: FEDERATION_RATE } });
  return Promise.resolve();
}

/**
 * The installation key (Phase 6 slice 6i; D-P6i-0-8): this server holds the private Ed25519 key of its installation and
 * seals what the database built (a lot-transfer package, a federation request or answer); the database holds the public
 * keys and verifies every seal itself (kernel 1220). DEMO-ONLY as a file: {installationCode, privateKeyPkcs8 (base64
 * DER)}; production keeps the key in a KMS or HSM behind the same two functions.
 *
 * What is signed is the kernel's platform.seal_message: `ebmr.<purpose>.v1|<SHA-256 hex of the payload's UTF-8>`, so a
 * seal of one purpose never verifies as another.
 */
import { createHash, createPrivateKey, createPublicKey, sign, type KeyObject } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { z } from 'zod';

export type SealPurpose = 'transfer-package' | 'federation-request' | 'federation-answer';

const KeyFile = z.strictObject({ installationCode: z.string().regex(/^[A-Z0-9][A-Z0-9-]{1,31}$/), privateKeyPkcs8: z.string().min(1), label: z.string().optional() });

export interface InstallationKey {
  installationCode: string;
  /** The raw 32-byte public key, standard base64 (what platform.installation_identity holds). */
  publicKey: string;
  seal(purpose: SealPurpose, payload: string): string;
}

export function sealMessage(purpose: SealPurpose, payload: string): Buffer {
  return Buffer.from(`ebmr.${purpose}.v1|${createHash('sha256').update(payload, 'utf8').digest('hex')}`, 'utf8');
}

export function rawPublicKeyOf(key: KeyObject): string {
  const x = createPublicKey(key).export({ format: 'jwk' }).x;
  if (!x) throw new Error('the installation key is not an Ed25519 key');
  return Buffer.from(x, 'base64url').toString('base64');
}

export function installationKeyOf(privateKey: KeyObject, installationCode: string): InstallationKey {
  if (privateKey.asymmetricKeyType !== 'ed25519') throw new Error('the installation key is not an Ed25519 key');
  return {
    installationCode,
    publicKey: rawPublicKeyOf(privateKey),
    seal: (purpose, payload) => sign(null, sealMessage(purpose, payload), privateKey).toString('base64'),
  };
}

/** Reads the DEMO-ONLY key file; null when none is configured. */
export function loadInstallationKey(file: string | null): InstallationKey | null {
  if (!file) return null;
  const k = KeyFile.parse(JSON.parse(readFileSync(file, 'utf8')));
  const privateKey = createPrivateKey({ key: Buffer.from(k.privateKeyPkcs8, 'base64'), format: 'der', type: 'pkcs8' });
  return installationKeyOf(privateKey, k.installationCode);
}

/**
 * The reads of the transfers namespace (Phase 6 slice 6i; contract ns/transfers.ts; kernel 1220, site services 0980,
 * 0981). Every value is the database's: the installation identity and peers, the outbound packages with their stored
 * payload and seal, the receipts with the carried content, the rule resolutions re-resolved at this site and the hold
 * time left at database time, and the installation alarms.
 */
import type pg from 'pg';
import type {
  InstallationAlarmView,
  InstallationIdentityView,
  PeerInstallationView,
  TransferPackageFileView,
  TransferPackageView,
  TransferReceiptSummaryView,
  TransferReceiptView,
} from '@ebmr/api-contract';
import type { AppContext } from '../../platform/context.ts';
import { refusal } from '../../platform/http/refusal.ts';
import { peopleOf, personRef, usOf } from '../common/people.ts';
import type { InstallationKey } from './keys.ts';

type Db = Pick<pg.Pool, 'query'>;

const notFound = (code: string, what: string) =>
  refusal(404, { code, kind: 'INVALID_INPUT', whatHappened: `There is no such ${what}.`, whatYouCanDo: [`Open the ${what} from its list.`], controls: ['DI-31'] });

export async function identity(db: Db, key: InstallationKey | null): Promise<InstallationIdentityView | null> {
  const { rows } = await db.query<{ code: string; site: string; edition: 'TABLETS' | 'INJECTABLES'; fp: string; version: number; pk: string }>(
    `select i.installation_code as code, i.site_code as site, i.edition, i.key_fingerprint as fp, i.version, encode(i.public_key, 'base64') as pk
       from platform.installation_identity i order by i.version desc limit 1`);
  const r = rows[0];
  if (!r) return null;
  return { installationCode: r.code, siteCode: r.site, edition: r.edition, keyFingerprint: r.fp, keyVersion: r.version, serverHoldsKey: key?.publicKey === r.pk && key.installationCode === r.code };
}

interface PeerRow {
  id: string;
  installation_code: string;
  site_code: string;
  edition: 'TABLETS' | 'INJECTABLES';
  base_url: string;
  key_fingerprint: string;
  state: PeerInstallationView['state'];
  proposed_by_person: string;
  proposed_us: string;
  approved_by_person: string | null;
  approved_us: string | null;
}

export async function peers(app: AppContext, db: Db, id?: string): Promise<PeerInstallationView[]> {
  const { rows } = await db.query<PeerRow>(
    `select p.id, p.installation_code, p.site_code, p.edition, p.base_url, p.key_fingerprint, platform.peer_installation_state(p.id) as state,
            p.proposed_by_person, ${usOf('p.proposed_at')} as proposed_us, a.approved_by_person, case when a.peer_id is null then null else ${usOf('a.approved_at')} end as approved_us
       from platform.peer_installation p left join platform.peer_installation_approval a on a.peer_id = p.id
      where $1::uuid is null or p.id = $1::uuid
      order by p.installation_code, p.proposed_at desc`, [id ?? null]);
  const people = await peopleOf(db, rows.flatMap((r) => [r.proposed_by_person, r.approved_by_person]));
  return rows.map((r) => ({
    peerId: r.id,
    installationCode: r.installation_code,
    siteCode: r.site_code,
    edition: r.edition,
    baseUrl: r.base_url,
    keyFingerprint: r.key_fingerprint,
    state: r.state,
